    @push('scripts')
        <script src="{{ asset('AdminLTE-3.2.0/plugins/datatables/jquery.dataTables.min.js') }}"></script><script src="{{ asset('AdminLTE-3.2.0/plugins/datatables-bs4/js/dataTables.bootstrap4.min.js') }}"></script>
        <script src="{{ asset('AdminLTE-3.2.0/plugins/select2/js/select2.full.min.js') }}"></script><script src="{{ asset('AdminLTE-3.2.0/plugins/sweetalert2/sweetalert2.min.js') }}"></script>
        <script>
        $(function(){
            const expandedGroups=new Set();
            const table=$('#product-groups-table').DataTable({processing:true,serverSide:true,autoWidth:false,ajax:"{{ route('admin.product-groups.data') }}",columns:[
                {data:'DT_RowIndex',name:'DT_RowIndex',orderable:false,searchable:false},{data:'product_id',name:'product_groups.product_id',visible:false,searchable:false},{data:'name',name:'product_groups.name'},{data:'product_name',name:'products.name'},{data:'description',name:'product_groups.description',defaultContent:'-'},{data:'banner_description',name:'product_groups.banner_description',defaultContent:'-'},{data:'sort_order',name:'product_groups.sort_order'},{data:'status',name:'product_groups.is_active',searchable:false},{data:'created_at',name:'product_groups.created_at'},{data:'actions',name:'actions',orderable:false,searchable:false}
            ],orderFixed:{pre:[[1,'asc']]},order:[[6,'asc']],drawCallback:function(){const rows=this.api().rows({page:'current'});let previousProduct=null;rows.every(function(){const group=this.data(),key=String(group.product_id),expanded=expandedGroups.has(key),row=$(this.node()).attr('data-relation-group',key).toggle(expanded);if(key===String(previousProduct))return;const toggle=$('<button/>',{type:'button',class:'btn btn-link text-dark font-weight-bold p-0 relation-folder-toggle','aria-expanded':String(expanded)}).attr('data-group-key',key);toggle.append($('<i/>',{class:'fas '+(expanded?'fa-folder-open':'fa-folder')+' mr-2'}));toggle.append(document.createTextNode('Product #'+group.product_id+' · '+group.product_name));row.before($('<tr/>',{class:'relation-group-row'}).append($('<td/>',{colspan:9}).append(toggle)));previousProduct=group.product_id;});},language:{processing:'Memproses...',search:'Cari:',lengthMenu:'Tampilkan _MENU_ data',info:'Menampilkan _START_–_END_ dari _TOTAL_ data',infoEmpty:'Belum ada data Product Group',infoFiltered:'(difilter dari _MAX_ total data)',zeroRecords:'Product Group tidak ditemukan',emptyTable:'Belum ada Product Group. Silakan tambahkan data pertama.',paginate:{first:'Pertama',last:'Terakhir',next:'Berikutnya',previous:'Sebelumnya'}}});
            $('#product-groups-table tbody').on('click','.relation-folder-toggle',function(){const key=String($(this).attr('data-group-key')),expanded=!expandedGroups.has(key);if(expanded)expandedGroups.add(key);else expandedGroups.delete(key);$(this).attr('aria-expanded',String(expanded)).find('i').toggleClass('fa-folder',!expanded).toggleClass('fa-folder-open',expanded);$('#product-groups-table tbody tr[data-relation-group]').each(function(){if($(this).attr('data-relation-group')===key)$(this).toggle(expanded);});});
            const modal=$('#group-modal'),form=$('#group-form'),errors=$('#form-errors'),save=$('#btn-save-group');let editing=false;
            $('#product_id').select2({theme:'bootstrap4',dropdownParent:modal,placeholder:'Pilih product',allowClear:true,width:'100%'});
            function refreshNameRemoveButtons(){const rows=$('#group-names .name-row');rows.find('.btn-remove-name').prop('disabled',rows.length===1);$('#btn-add-name').prop('disabled',rows.length>=50);}
            function addNameInput(value=''){if($('#group-names .name-row').length>=50)return;const row=$('<div class="input-group mb-2 name-row"></div>');const input=$('<input>',{class:'form-control name-input',name:'names[]',type:'text',maxlength:150,required:true,placeholder:'Nama Product Group'}).val(value);const append=$('<div class="input-group-append"></div>');const remove=$('<button>',{type:'button',class:'btn btn-outline-danger btn-remove-name',title:'Hapus input nama'}).html('<i class="fas fa-times"></i>');append.append(remove);row.append(input,append);$('#group-names').append(row);refreshNameRemoveButtons();}
            function addDescriptionInput(value=''){if($('#description-items .description-row').length>=100)return;const row=$('<div class="input-group mb-2 description-row"></div>');const input=$('<input>',{class:'form-control',name:'description_items[]',type:'text',maxlength:2000,placeholder:'Tulis satu poin tentang produk'}).val(value);const append=$('<div class="input-group-append"></div>');const remove=$('<button>',{type:'button',class:'btn btn-outline-danger btn-remove-description',title:'Hapus poin'}).html('<i class="fas fa-times"></i>');append.append(remove);row.append(input,append);$('#description-items').append(row);}
            function reset(){form[0].reset();$('#product_id').val('').trigger('change');$('#group-names').empty();addNameInput();$('#description-items').empty();addDescriptionInput();errors.addClass('d-none').empty();$('#sort_order_custom').val('0');$('#sort_order').val({{ $nextSortOrder }});form.find('input[name="_method"]').remove();save.prop('disabled',false);}
            $('#btn-add-name').on('click',()=>addNameInput());$('#group-names').on('click','.btn-remove-name',function(){$(this).closest('.name-row').remove();refreshNameRemoveButtons();});
            $('#btn-add-description').on('click',()=>addDescriptionInput());$('#description-items').on('click','.btn-remove-description',function(){$(this).closest('.description-row').remove();});
            $('#btn-add-group').on('click',function(){editing=false;reset();form.attr('action',"{{ route('admin.product-groups.store') }}");$('#modal-title').text('Tambah Product Group');save.find('span').text('Simpan Product Group');$('#sort-order-help').text('Nomor berikutnya dari database: {{ $nextSortOrder }}.');modal.modal('show');});
            $('#sort_order').on('input',()=>$('#sort_order_custom').val('1'));modal.on('hidden.bs.modal',reset);
            $('#product-groups-table').on('click','[data-action="edit"]',function(){const row=table.row($(this).closest('tr')).data();if(!row)return;editing=true;reset();form.attr('action',"{{ route('admin.product-groups.update', ':id') }}".replace(':id',row.id));form.append('<input type="hidden" name="_method" value="PUT">');$('#modal-title').text('Edit Product Group');save.find('span').text('Simpan Perubahan');$('#product_id').val(String(row.product_id)).trigger('change');$('#group-names .name-input').val(row.name);$('#description-items').empty();const points=String(row.description||'').split(/\r\n|\r|\n|<br\s*\/?\s*>/i).map(point=>point.trim()).filter(Boolean);(points.length?points:['']).forEach(point=>addDescriptionInput(point.replace(/^\s*(?:(?:[-*•])\s+|\d+[.)]\s*)/u,'')));$('#banner_description').val(row.banner_description||'');$('#sort_order').val(row.sort_order);$('#sort_order_custom').val('0');$('#is_active').val(row.is_active?'1':'0');modal.modal('show');});
            form.on('submit',function(e){e.preventDefault();errors.addClass('d-none').empty();save.prop('disabled',true);$.ajax({url:form.attr('action'),method:'POST',data:form.serialize(),headers:{Accept:'application/json'}}).done(function(resp){modal.modal('hide');table.ajax.reload(null,false);Swal.fire({icon:'success',title:'Berhasil',text:resp.message,timer:1700,showConfirmButton:false});}).fail(function(xhr){if(xhr.status===422&&xhr.responseJSON?.errors){errors.html(Object.values(xhr.responseJSON.errors).flat().map(msg=>`<div>${$('<div>').text(msg).html()}</div>`).join('')).removeClass('d-none');}else{Swal.fire({icon:'error',title:'Gagal',text:xhr.responseJSON?.message||'Product Group gagal disimpan.'});}}).always(()=>save.prop('disabled',false));});
            $('#product-groups-table').on('click','[data-action="delete"]',function(){const row=table.row($(this).closest('tr')).data();if(!row)return;Swal.fire({icon:'warning',title:'Hapus Product Group?',text:`Data "${row.name}" beserta variant dan field terkait akan dihapus.`,showCancelButton:true,confirmButtonText:'Ya, hapus',cancelButtonText:'Batal',confirmButtonColor:'#dc3545'}).then(result=>{if(!result.isConfirmed)return;$.ajax({url:"{{ route('admin.product-groups.destroy', ':id') }}".replace(':id',row.id),method:'POST',data:{_token:$('meta[name="csrf-token"]').attr('content'),_method:'DELETE'},headers:{Accept:'application/json'}}).done(resp=>{table.ajax.reload(null,false);Swal.fire({icon:'success',title:'Berhasil',text:resp.message,timer:1700,showConfirmButton:false});}).fail(xhr=>Swal.fire({icon:'error',title:'Gagal',text:xhr.responseJSON?.message||'Product Group gagal dihapus.'}));});});
        });
        </script>
    @endpush
</x-app-layout>
